CREATE OR REPLACE FUNCTION bitwise_xor_or_default(input_values integer[], default_value integer = 0)
RETURNS integer AS $$
DECLARE
    result integer;
BEGIN
    -- Application of bitwise XOR logic on non-null elements
    SELECT COALESCE(BIT_XOR(v), default_value) INTO result
    FROM UNNEST(input_values) AS x(v)
    WHERE v IS NOT NULL;

    RETURN result;
END;
$$ LANGUAGE plpgsql;

