CREATE OR REPLACE FUNCTION bitwise_xor_agg(arr integer[], default_val integer)
RETURNS integer AS $$
DECLARE
    xor_result integer := 0;
    non_null_exists boolean := false;
BEGIN
    -- Iterate over each element in the input array
    IF arr IS NULL THEN
        RETURN default_val;
    END IF;

    FOR i IN 1..array_length(arr, 1) LOOP
        -- Check if the current element is non-null
        IF arr[i] IS NOT NULL THEN
            xor_result := xor_result # arr[i];
            non_null_exists := true;
        END IF;
    END LOOP;

    -- If there are non-null values, return the computed XOR result
    IF non_null_exists THEN
        RETURN xor_result;
    ELSE
        -- If all values are null, return the default value
        RETURN default_val;
    END IF;
END;
$$ LANGUAGE plpgsql;

